const incoming = $('WhatsApp Trigger').item.json || {};
const rawState = items[0].json?.value ? JSON.parse(items[0].json.value) : null;
const state = rawState || {
  mode: null,
  step: 0,
  answers: {
    address: '',
    perimeter: null,
    facade: null,
    heights: null,
    neighbors: null,
    price_m2: null,
    elements: [],
    photos: { fachada: 0, medianeras: 0, terraza: 0, cubierta: 0 },
    windows_m2: 0,
    terraces_m2: 0
  },
  confirmations: { catastro: false, resumen: false },
  summary: null,
  documents: []
};

const msg = incoming.messages?.[0] || incoming.body || incoming;
const text = String(msg?.text?.body || '').trim();
const type = msg?.type || (msg?.image ? 'image' : 'text');
const reply = { action: 'ask', text: '', requiresPhotos: false, state, documents: [] };
const lower = text.toLowerCase();

function ensureMode(){
  if(state.mode) return;
  if(/presupuesto|aislamiento|sate/.test(lower)) state.mode='presupuesto';
  else if(/valoraci[óo]n|valuaci|precio/.test(lower)) state.mode='valoracion';
}

function askNext(){
  const qVal = [
    'Para la valoración necesito la dirección completa.',
    '¿Cuál es el perímetro exterior en metros?',
    '¿Cuál es la superficie de fachada (m²)?',
    '¿Cuántas alturas tiene el edificio?',
    '¿Cuántas viviendas o vecinos hay?',
    '¿Qué precio por metro cuadrado debemos usar?'
  ];
  const qPre = [
    'Para empezar, dime la dirección completa.',
    'Indica el perímetro exterior en metros.',
    'Indica la superficie de fachada en m².',
    '¿Cuántas alturas tiene el edificio?',
    '¿Cuántos vecinos o viviendas hay?',
    'Lista los elementos a desmontar (aires, antenas, tuberías, cables, canaletas, placas solares).',
    'Necesito la foto de la fachada 1 indicando si es medianera.',
    'Foto de la fachada 2.',
    'Foto de la fachada 3.',
    'Foto de la fachada 4 (indica si es medianera).',
    'Si hay terrazas cerradas envía foto y superficie, si no responde

.',
    'Por último, envía una foto de la cubierta.'
  ];
  const questions = state.mode === 'valoracion' ? qVal : qPre;
  if(state.step < questions.length){
    reply.text = questions[state.step];
    reply.requiresPhotos = state.step >= 6 && state.mode === 'presupuesto';
    return true;
  }
  return false;
}

function fakeCatastroLookup(address){
  return {
    perimeter: 120,
    facade: 480,
    heights: 4,
    neighbors: 16,
    ref: 'FAKE-REF-1234'
  };
}

function buildResumen(){
  const ans = state.answers;
  const lines = [
    `Dirección: ${ans.address || '—'}`,
    `Perímetro: ${ans.perimeter ?? '—'} m`,
    `Fachada: ${ans.facade ?? '—'} m²`,
    `Alturas: ${ans.heights ?? '—'}`,
    `Vecinos: ${ans.neighbors ?? '—'}`
  ];
  if(state.mode === 'valoracion') lines.push(`Precio m²: ${ans.price_m2 ?? '—'}`);
  if(state.mode === 'presupuesto'){
    lines.push(`Fotos fachada recibidas: ${ans.photos.fachada}`);
    lines.push(`Fotos medianeras marcadas: ${ans.photos.medianeras}`);
    lines.push(`Fotos terrazas: ${ans.photos.terraza}`);
    lines.push(`Fotos cubierta: ${ans.photos.cubierta}`);
  }
  state.summary = lines.join('
');
  return state.summary;
}

if(type === 'image'){
  state.answers.photos.fachada += 1;
  reply.text = 'Foto recibida. Si corresponde a una medianera responde

.';
  reply.requiresPhotos = false;
  state.step = Math.min(state.step + 1, state.mode === 'presupuesto' ? 12 : state.step);
  return [{ json: reply }];
}

ensureMode();
if(!state.mode){
  reply.text = '¿Quieres iniciar un presupuesto de fachada/cubierta o una valoración?';
  return [{ json: reply }];
}

if(!text){
  askNext();
  return [{ json: reply }];
}

if(state.mode === 'valoracion'){
  switch(state.step){
    case 0:
      state.answers.address = text;
      const datos = fakeCatastroLookup(text);
      state.answers.perimeter = datos.perimeter;
      state.answers.facade = datos.facade;
      state.answers.heights = datos.heights;
      state.answers.neighbors = datos.neighbors;
      state.confirmations.catastro = true;
      reply.text = `He consultado Catastro (ref ${datos.ref}).
Perímetro ${datos.perimeter} m, fachada ${datos.facade} m², alturas ${datos.heights}, vecinos ${datos.neighbors}. ¿Quieres ajustar alguno?`;
      state.summary = buildResumen();
      state.step = 1;
      return [{ json: reply }];
    case 1:
      state.answers.perimeter = Number(text.replace(',', '.')) || state.answers.perimeter;
      state.step++; break;
    case 2:
      state.answers.facade = Number(text.replace(',', '.')) || state.answers.facade;
      state.step++; break;
    case 3:
      state.answers.heights = parseInt(text, 10) || state.answers.heights;
      state.step++; break;
    case 4:
      state.answers.neighbors = parseInt(text, 10) || state.answers.neighbors;
      state.step++; break;
    case 5:
      state.answers.price_m2 = Number(text.replace(',', '.')) || state.answers.price_m2;
      state.step++; break;
    default:
      state.step++;
  }
  if(state.step >= 6){
    const valor = (state.answers.facade || 0) * (state.answers.price_m2 || 0);
    reply.text = `${buildResumen()}
Valoración estimada: ${valor.toFixed(2)} €. ¿Generamos el PDF y lo cargamos en Odoo?`;
    state.documents = [{ type: 'valoracion', total: valor }];
  } else {
    askNext();
  }
  return [{ json: reply }];
}

// Presupuesto
switch(state.step){
  case 0:
    state.answers.address = text;
    const datos = fakeCatastroLookup(text);
    state.answers.perimeter = datos.perimeter;
    state.answers.facade = datos.facade;
    state.answers.heights = datos.heights;
    state.answers.neighbors = datos.neighbors;
    reply.text = `RC ${datos.ref}. Tomo perímetro ${datos.perimeter} m y fachada ${datos.facade} m². Ajusta si es necesario.`;
    state.summary = buildResumen();
    state.step = 1;
    return [{ json: reply }];
  case 1:
    state.answers.perimeter = Number(text.replace(',', '.')) || state.answers.perimeter;
    state.step++; break;
  case 2:
    state.answers.facade = Number(text.replace(',', '.')) || state.answers.facade;
    state.step++; break;
  case 3:
    state.answers.heights = parseInt(text,10) || state.answers.heights;
    state.step++; break;
  case 4:
    state.answers.neighbors = parseInt(text,10) || state.answers.neighbors;
    state.step++; break;
  case 5:
    state.answers.elements = text.split(/[,;]+/).map(x=>x.trim()).filter(Boolean);
    state.step++;
    reply.text = 'Perfecto. Vamos con las fotos de las fachadas.';
    reply.requiresPhotos = true;
    return [{ json: reply }];
  case 10:
    if(/^no$/i.test(text)){
      state.answers.terraces_m2 = 0;
    } else {
      state.answers.terraces_m2 = Number(text.replace(',', '.')) || state.answers.terraces_m2;
    }
    state.step++;
    askNext();
    return [{ json: reply }];
  default:
    state.step++;
}

if(state.step >= 12){
  const areaEfectiva = Math.max((state.answers.facade || 0) - (state.answers.windows_m2 || 0) - (state.answers.terraces_m2 || 0), 0);
  const costeBase = areaEfectiva * 65; // placeholder
  reply.text = `${buildResumen()}
Área efectiva tras huecos: ${areaEfectiva.toFixed(2)} m². Coste estimado ${costeBase.toFixed(2)} €. ¿Generamos presupuesto en Odoo y lo enviamos?`;
  state.documents = [{ type: 'presupuesto', total: costeBase }];
} else {
  askNext();
}

return [{ json: reply }];
